   N("ML pipelines & orchestration", "Reproducible data and training pipelines.", ["feature stores", "orchestration", "data versioning"], ["madewithml", "airflow"]),
   N("Experiment tracking & registry", "Track every run; promote models through stages.", ["MLflow", "model registry", "lineage"], ["mlflow"]),
   N("Monitoring & drift", "Detect when the world changes under your model.", ["data drift", "concept drift", "shadow deploys", "retraining triggers"], ["madewithml", "rm-mlops"]),
   N("Containers & Kubernetes for ML", "Package and scale training and serving.", ["Docker", "GPU scheduling", "autoscaling"], ["docker", "k8s"]),
